DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(snap, &pe)) {
        do {
            if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; }
        } while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return pid;
}

int wmain() {
    DWORD pid = GetPid(L"[进程名]");          // ← 把进程名填这里
    if (!pid) { printf("pid not found\n"); return 1; }

    HANDLE h = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE |
                           PROCESS_VM_OPERATION | PROCESS_QUERY_INFORMATION,
                           FALSE, pid);
    if (!h) { printf("OpenProcess failed: %lu\n", GetLastError()); return 1; }

    // 拿主模块基址
    HMODULE mods[1024]; DWORD need = 0;
    if (!EnumProcessModules(h, mods, sizeof(mods), &need)) {
        printf("EnumProcessModules failed: %lu\n", GetLastError()); return 1;
    }
    printf("pid=%lu base=%p\n", pid, (void*)mods[0]);
    CloseHandle(h);
    return 0;
}
