// IOCTL 码（占位，按需改）
#define IOCTL_READ_MEM   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE_MEM  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_GET_BASE   CTL_CODE(FILE_DEVICE_UNKNOWN, 0x802, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQUEST {
    ULONG   Pid;
    PVOID   Address;
    PVOID   Buffer;
    SIZE_T  Size;
    SIZE_T  Returned;
    WCHAR   ModuleName[64];   // 只给 GetBase 用
    PVOID   ModuleBase;
} RW_REQUEST, *PRW_REQUEST;

// 通过 Pid 拿 EPROCESS 再拿进程对象
static PEPROCESS GetProcessByPid(ULONG pid)
{
    PEPROCESS proc = NULL;
    if (NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &proc)))
        return proc;
    return NULL;
}

// MmCopyVirtualMemory 读写核心
static NTSTATUS ReadWriteMemory(PRW_REQUEST req, BOOLEAN bWrite)
{
    PEPROCESS src = GetProcessByPid(req->Pid);
    if (!src) return STATUS_INVALID_PARAMETER;

    PEPROCESS dst = PsGetCurrentProcess();
    SIZE_T copied = 0;
    NTSTATUS st;

    if (bWrite) {
        // 从当前进程写目标（也可反过来，看调用方语义）
        st = MmCopyVirtualMemory(dst, req->Buffer, src, req->Address,
                                 req->Size, KernelMode, &copied);
    } else {
        st = MmCopyVirtualMemory(src, req->Address, dst, req->Buffer,
                                 req->Size, KernelMode, &copied);
    }
    ObDereferenceObject(src);
    req->Returned = copied;
    return st;
}

