static NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp)
{
    UNREFERENCED_PARAMETER(dev);
    PIO_STACK_LOCATION  stack = IoGetCurrentIrpStackLocation(irp);
    PVOID   buf  = irp->AssociatedIrp.SystemBuffer;
    ULONG   inlen  = stack->Parameters.DeviceIoControl.InputBufferLength;
    ULONG   code   = stack->Parameters.DeviceIoControl.IoControlCode;
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG    outlen = 0;

    if (!buf || inlen < sizeof(RW_REQUEST)) {
        st = STATUS_BUFFER_TOO_SMALL;
        goto done;
    }

    PRW_REQUEST req = (PRW_REQUEST)buf;

    // 进程对象本身可用 ObRegisterCallbacks 保护，这里先不挂
    switch (code) {
    case IOCTL_READ_MEM:
        st = ReadWriteMemory(req, FALSE);
        break;
    case IOCTL_WRITE_MEM:
        st = ReadWriteMemory(req, TRUE);
        break;
    default:
        break;
    }
    outlen = sizeof(RW_REQUEST);

done:
    irp->IoStatus.Status = st;
    irp->IoStatus.Information = outlen;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return st;
}

