#include "RwDrv.h"

static NTSTATUS ResolvePid(ULONG pid, PEPROCESS* out) {
    return PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, out);
}

static NTSTATUS DoCopy(ULONG pid, PVOID addr, PVOID buf, SIZE_T size, BOOLEAN write) {
    PEPROCESS proc = NULL;
    NTSTATUS st = ResolvePid(pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);
    SIZE_T done = 0;
    st = MmCopyVirtualMemory(
            write ? PsGetCurrentProcess() : proc,
            write ? buf : addr,
            write ? proc : PsGetCurrentProcess(),
            write ? addr : buf,
            size, KernelMode, &done);
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
    return st;
}

