```c
#include "rw_driver.h"

static PDEVICE_OBJECT g_Device = NULL;

static NTSTATUS DoRead(PRW_REQUEST req)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T copied = 0;
    st = MmCopyVirtualMemory(proc, req->Addr, PsGetCurrentProcess(),
                             req->Buffer, req->Size, KernelMode, &copied);
    ObDereferenceObject(proc);
    req->Returned = copied;
    return st;
}

static NTSTATUS DoWrite(PRW_REQUEST req)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    SIZE_T copied = 0;
    st = MmCopyVirtualMemory(PsGetCurrentProcess(), req->Buffer,
                             proc, req->Addr, req->Size, KernelMode, &copied);
    ObDereferenceObject(proc);
    req->Returned = copied;
    return st;
}

/* 遍历目标进程模块链表找基址，替代 EnumProcessModules */
static NTSTATUS DoGetBase(PRW_BASE base)
{
    PEPROCESS proc = NULL;
    NTSTATUS st = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)base->Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    KAPC_STATE apc;
    KeStackAttachProcess(proc, &apc);

    PPEB peb = PsGetProcessPeb(proc);
    if (!peb) { KeUnstackDetachProcess(&apc); ObDereferenceObject(proc); return STATUS_NOT_FOUND; }

    UNICODE_STRING target;
    RtlInitUnicodeString(&target, base->ModuleName);
    NTSTATUS found = STATUS_NOT_FOUND;

    __try {
        for (PLIST_ENTRY e = peb->Ldr->InLoadOrderModuleList.Flink;
             e != &peb->Ldr->InLoadOrderModuleList; e = e->Flink)
        {
            PLDR_DATA_TABLE_ENTRY ent = CONTAINING_RECORD(e, LDR_DATA_TABLE_ENTRY, InLoadOrderLinks);
            if (RtlEqualUnicodeString(&ent->BaseDllName, &target, TRUE)) {
                base->Base      = ent->DllBase;
                base->ImageSize = ent->SizeOfImage;
                found = STATUS_SUCCESS;
                break;
            }
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) { found = STATUS_ACCESS_VIOLATION; }

    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(proc);
