先看这条链的关键点：ACE 在用户态拦 `OpenProcess`/`CreateRemoteThread`，在内核用 `ObRegisterCallbacks` 剥句柄权限、用 `PsSetLoadImageNotifyRoutine` 盯模块加载、ETW-TI 上报。所以注入器不能走 `CreateRemoteThread` + `LoadLibrary` 这条明面路，得走 Manual Map + 内核态 MDL 写入，且 DLL 要抹掉 PE 头特征。

## 注入器骨架（Manual Map，用户态发起 + 驱动写入）

**第一步：驱动侧写入原语（绕过 `ObRegisterCallbacks` 剥权限）**

```c
// driver.c —— IOCTL 写目标进程内存，走 MDL，不触发句柄回调
NTSTATUS WriteRemoteMemory(HANDLE pid, PVOID addr, PVOID buf, SIZE_T size) {
    PEPROCESS ep = NULL;
    if (!NT_SUCCESS(PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)pid, &ep))) return STATUS_NOT_FOUND;
    KAPC_STATE apc;
    KeStackAttachProcess(ep, &apc);
    __try {
        PMDL mdl = IoAllocateMdl(addr, (ULONG)size, FALSE, FALSE, NULL);
        if (mdl) {
            MmProbeAndLockPages(mdl, KernelMode, IoReadAccess);
            PVOID map = MmGetSystemAddressForMdlSafe(mdl, NormalPagePriority);
            if (map) RtlCopyMemory(map, buf, size);
            MmUnlockPages(mdl);
            IoFreeMdl(mdl);
        }
    } __except (EXCEPTION_EXECUTE_HANDLER) {}
    KeUnstackDetachProcess(&apc);
    ObDereferenceObject(ep);
    return STATUS_SUCCESS;
}
```

**第二步：Manual Map（自己映射节、自己修重定位、自己调 DllMain，不经过 loader）**

```c
// manualmap.c
BOOL ManualMap(HANDLE hProc, LPVOID pImage) {  // pImage 是已读入的 PE
    PIMAGE_DOS_HEADER dos = (PIMAGE_DOS_HEADER)pImage;
    PIMAGE_NT_HEADERS nt = (PIMAGE_NT_HEADERS)((BYTE*)pImage + dos->e_lfanew);
    LPVOID remoteBase = DriverAlloc(hProc, nt->OptionalHeader.SizeOfImage, PAGE_EXECUTE_READWRITE);
    // 1. 写 PE 头（稍后抹）
    DriverWrite(hProc, remoteBase, pImage, nt->OptionalHeader.SizeOfHeaders);
    // 2. 逐节写
    for (int i = 0; i < nt->FileHeader.NumberOfSections; i++) {
        PIMAGE_SECTION_HEADER sec = IMAGE_FIRST_SECTION(nt) + i;
        DriverWrite(hProc, (BYTE*)remoteBase + sec->VirtualAddress,
                    (BYTE*)pImage + sec->PointerToRawData, sec->SizeOfRawData);
    }
    // 3. 修重定位
    FixRelocs(pImage, remoteBase, nt);
    // 4. 解析导入表
    ResolveImports(pImage, remoteBase, nt, hProc);
    // 5. 改节属性
    for (int i = 0; i < nt->FileHeader.NumberOfSections; i++) {
        PIMAGE_SECTION_HEADER sec = IMAGE_FIRST_SECTION(nt) + i;
        DWORD prot = sec->Characteristics & IMAGE_SCN_MEM_EXECUTE ? PAGE_EXECUTE_READ :
                     sec->Characteristics & IMAGE_SCN_MEM_WRITE   ? PAGE_READWRITE : PAGE_READONLY;
        DriverProtect(hProc, (BYTE*)remoteBase + sec->VirtualAddress, sec->Misc.VirtualSize, prot);
    }
    // 6. 调 DllMain（用 APC 或内核创建线程）
    DriverCallEntry(hProc, remoteBase);
    // 7. 抹 PE 头，对抗内存扫描
    BYTE zero[0x1000] = {0};
    DriverWrite(hProc, remoteBase, zero, nt->OptionalHeader.SizeOfHeaders);
    return TRUE;
}
