## 二、驱动读写模块（WDM，核心代码）

```c
// ace_rw.c —— 内核读写驱动骨架
#include <ntifs.h>
#include <ntddk.h>

#define DEVICE_NAME L"\\Device\\AceRw"
#define SYMLINK_NAME L"\\DosDevices\\AceRw"
#define IOCTL_READ_MEM  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_WRITE_MEM CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

typedef struct _RW_REQUEST {
    ULONG  Pid;
    PVOID  Address;
    PVOID  Buffer;
    SIZE_T Size;
} RW_REQUEST, *PRW_REQUEST;

// 用 MmCopyVirtualMemory 绕过 ObRegisterCallbacks 的句柄剥权限
NTSTATUS DoReadWrite(PRW_REQUEST req, BOOLEAN bWrite) {
    PEPROCESS srcProc = NULL, dstProc = NULL;
    NTSTATUS status;
    SIZE_T bytes = 0;

    status = PsLookupProcessByProcessId((HANDLE)(ULONG_PTR)req->Pid, &srcProc);
    if (!NT_SUCCESS(status)) return status;

    dstProc = PsGetCurrentProcess();
    if (bWrite) {
        status = MmCopyVirtualMemory(dstProc, req->Buffer, srcProc, req->Address, req->Size, KernelMode, &bytes);
    } else {
        status = MmCopyVirtualMemory(srcProc, req->Address, dstProc, req->Buffer, req->Size, KernelMode, &bytes);
    }
    ObDereferenceObject(srcProc);
    return status;
}

NTSTATUS DispatchIoctl(PDEVICE_OBJECT dev, PIRP irp) {
    PIO_STACK_LOCATION stack = IoGetCurrentIrpStackLocation(irp);
    ULONG code = stack->Parameters.DeviceIoControl.IoControlCode;
    PVOID buf = irp->AssociatedIrp.SystemBuffer;
    ULONG len = stack->Parameters.DeviceIoControl.InputBufferLength;
    NTSTATUS status = STATUS_INVALID_PARAMETER;

    if (len >= sizeof(RW_REQUEST)) {
        PRW_REQUEST req = (PRW_REQUEST)buf;
        if (code == IOCTL_READ_MEM)  status = DoReadWrite(req, FALSE);
        if (code == IOCTL_WRITE_MEM) status = DoReadWrite(req, TRUE);
    }
    irp->IoStatus.Status = status;
    irp->IoStatus.Information = 0;
    IoCompleteRequest(irp, IO_NO_INCREMENT);
    return status;
}

NTSTATUS DriverEntry(PDRIVER_OBJECT drv, PUNICODE_STRING reg) {
    UNICODE_STRING devName, symName;
    PDEVICE_OBJECT devObj;
    RtlInitUnicodeString(&devName, DEVICE_NAME);
    RtlInitUnicodeString(&symName, SYMLINK_NAME);
    IoCreateDevice(drv, 0, &devName, FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN, FALSE, &devObj);
    IoCreateSymbolicLink(&symName, &devName);
    drv->MajorFunction[IRP_MJ_CREATE] = drv->MajorFunction[IRP_MJ_CLOSE] = (PDRIVER_DISPATCH)DispatchIoctl;
    drv->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoctl;
    return STATUS_SUCCESS;
}
```

