// ue4_locate.cpp — 定位 GNames / GObjects 全局
#include <windows.h>
#include <tlhelp32.h>
#include <vector>
#include <cstdio>

static uintptr_t g_base = 0;
static size_t    g_size = 0;

bool GetModule(const wchar_t* modName) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, GetCurrentProcessId());
    if (snap == INVALID_HANDLE_VALUE) return false;
    MODULEENTRY32W me{ sizeof(me) };
    for (BOOL ok = Module32FirstW(snap, &me); ok; ok = Module32NextW(snap, &me)) {
        if (_wcsicmp(me.szModule, modName) == 0) {
            g_base = (uintptr_t)me.modBaseAddr;
            g_size = me.modBaseSize;
            break;
        }
    }
    CloseHandle(snap);
    return g_base != 0;
}

// 返回所有匹配的 RVA
std::vector<uintptr_t> ScanAOB(uintptr_t base, size_t size, const uint8_t* pat, const char* mask) {
    std::vector<uintptr_t> hits;
    size_t mlen = strlen(mask);
    if (mlen == 0 || mlen > size) return hits;
    for (size_t i = 0; i <= size - mlen; ++i) {
        size_t j = 0;
        for (; j < mlen; ++j) {
            if (mask[j] == 'x' && *(uint8_t*)(base + i + j) != pat[j]) break;
        }
        if (j == mlen) hits.push_back(base + i);
    }
    return hits;
}

