#define INDEX_PML4(va)  ((va >> 39) & 0x1FF)
#define INDEX_PDPT(va)  ((va >> 30) & 0x1FF)
#define INDEX_PD(va)    ((va >> 21) & 0x1FF)
#define INDEX_PT(va)    ((va >> 12) & 0x1FF)
#define PAGE_OFFSET(va) ((va) & 0xFFF)

#define PTE_PRESENT     (1ULL << 0)
#define PTE_RW          (1ULL << 1)
#define PTE_USER        (1ULL << 2)
#define PTE_PWT         (1ULL << 3)
#define PTE_PCD         (1ULL << 4)
#define PTE_PS          (1ULL << 7)      // PDPT/PD 大页
#define PTE_NX          (1ULL << 63)
#define PHY_MASK        0x000FFFFFFFFFF000ULL

// ---- 运行时上下文：随驱动加载确定，不要写死 ----
typedef struct _VA_CTX {
    HANDLE       pid;            // 目标进程 ID
    PEPROCESS    process;        // ObReferenceObjectByHandle 得到
    UINT64       cr3;            // DirectoryTableBase，物理地址
    UINT64       kpcrCr3;        // 系统 KPCR->KdVersionBlock 或自采，用于恢复
    ULONG        cpuIndex;
} VA_CTX, *PVA_CTX;

// ---- EPROCESS 偏移：从 PDB 符号取，下面为占位 ----
// 用 windbg: dt nt!_EPROCESS DirectoryTableBase  /  uf nt!PsGetProcessId
#define EPROCESS_DTB_OFFSET     0x028      // [偏移] 占位，必须按实际 build 用符号确认
#define EPROCESS_PID_OFFSET     0x440      // [偏移] 占位
