### 2. CR3 取法与恢复

```c
// 读当前 CPU 的 CR3（必须在目标上下文/被调度到的 CPU 上读，读的是"当前"CR3）
static __forceinline UINT64 ReadCr3(void)
{
    return __readcr3() & PHY_MASK;
}

// 取目标进程 CR3：直接读 EPROCESS.DirectoryTableBase
// 前提：已 PsLookupProcessByProcessId 拿到 PEPROCESS
static UINT64 GetProcessCr3(PEPROCESS process)
{
    // 占位偏移，按 build 用符号确认
    return *(UINT64*)((PUCHAR)process + EPROCESS_DTB_OFFSET) & PHY_MASK;
}

// 切换 CR3 到目标进程并在之后恢复
// 注意：__writecr3 必须关中断 + 只切单 CPU；多核必须用 KeSetSystemAffinityThread 绑核
static void SwitchCr3(UINT64 newCr3, UINT64* oldCr3Out)
{
    KIRQL irql = KeRaiseIrqlToDpcLevel();
    *oldCr3Out = __readcr3();
    __writecr3(newCr3);
    // 完成后调用方必须恢复：
    // __writecr3(*oldCr3Out); KeLowerIrql(irql);
    KeLowerIrql(irql);   // 这里仅示意，切换-恢复应成对包成函数
}
```

