        GetCommState(h, &dcb);
        dcb.BaudRate = 115200;
        dcb.ByteSize = 8;
        dcb.Parity   = NOPARITY;
        dcb.StopBits = ONESTOPBIT;
        dcb.fBinary  = TRUE;
        dcb.fParity  = FALSE;
        SetCommState(h, &dcb);

        COMMTIMEOUTS to{};
        to.ReadIntervalTimeout        = MAXDWORD;
        to.ReadTotalTimeoutMultiplier = 0;
        to.ReadTotalTimeoutConstant   = 0;
        to.WriteTotalTimeoutConstant  = 50;
        SetCommTimeouts(h, &to);
        return true;
    }

    // dx, dy 为相对位移；btn 为按键掩码（默认 0）
    bool move(int16_t dx, int16_t dy, uint8_t btn = 0) {
        if (h == INVALID_HANDLE_VALUE) return false;

        uint8_t buf[11];
        buf[0] = 0xAA;
        buf[1] = 0xA0;
        buf[2] = 0x08;
        buf[3] = (uint8_t)(dx & 0xFF);
        buf[4] = (uint8_t)((dx >> 8) & 0xFF);
        buf[5] = (uint8_t)(dy & 0xFF);
        buf[6] = (uint8_t)((dy >> 8) & 0xFF);
        buf[7] = 0x00;
        buf[8] = btn;

        uint16_t crc = crc16_modbus(buf, 9);
        buf[9]  = (uint8_t)(crc & 0xFF);
        buf[10] = (uint8_t)(crc >> 8);

        DWORD written = 0;
        return WriteFile(h, buf, sizeof(buf), &written, nullptr)
               && written == sizeof(buf);
    }

    void close() {
        if (h != INVALID_HANDLE_VALUE) { CloseHandle(h); h = INVALID_HANDLE_VALUE; }
    }
};
