DWORD GetPid(const wchar_t* name) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    if (Process32FirstW(snap, &pe)) {
        do { if (!_wcsicmp(pe.szExeFile, name)) { CloseHandle(snap); return pe.th32ProcessID; } }
        while (Process32NextW(snap, &pe));
    }
    CloseHandle(snap);
    return 0;
}

uint64_t GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    uint64_t base = 0;
    if (Module32FirstW(snap, &me)) {
        do { if (!_wcsicmp(me.szModule, mod)) { base = (uint64_t)me.modBaseAddr; break; } }
        while (Module32NextW(snap, &me));
    }
    CloseHandle(snap);
    return base;
}

template <typename T>
bool RPM(HANDLE h, uint64_t addr, T& out) {
    SIZE_T got = 0;
    return ReadProcessMemory(h, (LPCVOID)addr, &out, sizeof(T), &got) && got == sizeof(T);
}

uint64_t ResolveChain(HANDLE h, uint64_t base, uint64_t first, const std::vector<uint64_t>& offsets) {
    uint64_t addr = base + first;
    for (size_t i = 0; i < offsets.size(); ++i) {
        uint64_t ptr = 0;
        if (!RPM(h, addr, ptr) || !ptr) return 0;
        addr = ptr + offsets[i];
    }
    return addr;
}
