// rw.cpp —— 最小读写 + 模块基址 + 多级指针链解析
#include <windows.h>
#include <tlhelp32.h>
#include <stdio.h>

static DWORD GetPid(const wchar_t* name) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
    PROCESSENTRY32W pe{ sizeof(pe) };
    DWORD pid = 0;
    if (Process32FirstW(h, &pe))
        do { if (!_wcsicmp(pe.szExeFile, name)) { pid = pe.th32ProcessID; break; } }
        while (Process32NextW(h, &pe));
    CloseHandle(h);
    return pid;
}

static ULONG_PTR GetModuleBase(DWORD pid, const wchar_t* mod) {
    HANDLE h = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
    MODULEENTRY32W me{ sizeof(me) };
    ULONG_PTR base = 0;
    if (Module32FirstW(h, &me))
        do { if (!_wcsicmp(me.szModule, mod)) { base = (ULONG_PTR)me.modBaseAddr; break; } }
        while (Module32NextW(h, &me));
    CloseHandle(h);
    return base;
}

int wmain() {
    DWORD pid = GetPid(L"[进程名]");
    if (!pid) { wprintf(L"pid not found\n"); return 1; }

    HANDLE hp = OpenProcess(PROCESS_VM_READ | PROCESS_VM_WRITE | PROCESS_VM_OPERATION, FALSE, pid);
    if (!hp) { wprintf(L"OpenProcess fail %lu\n", GetLastError()); return 1; }

    ULONG_PTR modBase = GetModuleBase(pid, L"[模块名]");
    printf("pid=%lu base=%p\n", pid, (void*)modBase);

    // 多级指针链：[基址+偏移1] -> +偏移2 -> +字段偏移；偏移用占位符，逆向确认后替换
    ULONG_PTR addr = modBase + [偏移1];
    ULONG_PTR p = 0;
    ReadProcessMemory(hp, (LPCVOID)addr, &p, sizeof(p), nullptr);
    ReadProcessMemory(hp, (LPCVOID)(p + [偏移2]), &p, sizeof(p), nullptr);

    int hp_val = 0;
    ReadProcessMemory(hp, (LPCVOID)(p + [字段偏移_血量]), &hp_val, sizeof(hp_val), nullptr);
    printf("hp=%d @ %p\n", hp_val, (void*)(p + [字段偏移_血量]));

    // 写入前先 dump 原值做回滚
    int old = hp_val, nw = [目标值];
    WriteProcessMemory(hp, (LPVOID)(p + [字段偏移_血量]), &nw, sizeof(nw), nullptr);
    printf("write %d -> %d (rollback: write %d)\n", old, nw, old);

    CloseHandle(hp);
    return 0;
}
